try:
    print('>>> f = pow')
    print('>>> x = ""')
    print('>>> y = frozenset()')
    print('>>> f(x, y)')
    f = pow
    x = ""
    y = frozenset()
    print(f(x, y))
except Exception as e:
    print(type(e), ':', e)
print()
